) AS (
    VALUES
        ('EWA_ATOM_IMPORTANCE_FLOOR', 'float', 'atoms', 'Min importance for atom retention. Дробный порог (0–1). Используется как gate confidence/score: ниже порога — fallback на другую ветку orchestrator.', 'Min importance for atom retention. Float threshold (0–1). Used as confidence/score gate: below threshold — orchestrator fallback branch.', '0.15', '0–1', 'Atom scoring filter.', 'Atom scoring filter.', false, 1150),
        ('EWA_ATOM_LAYER_ENABLED', 'bool', 'atoms', 'Atom memory layer v1: ingest фактов в knowledge graph, retrieval в companion context. Зависит от Qdrant и embedding stack2. TTL/importance — соседние EWA_ATOM_* параметры.', 'Atom memory layer v1: fact ingest into knowledge graph, companion context retrieval. Depends on Qdrant and stack2 embeddings. TTL/importance: neighboring EWA_ATOM_* settings.', '0', '0|1', 'atoms/ingest.py, companion retrieval budget.', 'atoms/ingest.py, companion retrieval budget.', false, 1140),
        ('EWA_ATOM_RETRIEVAL_DROP_STALE', 'bool', 'atoms', 'Drop stale atoms at retrieval. Флаг вкл/выкл: 0 — выключено, 1 — включено. Значение хранится в Postgres; после «Сохранить» API подхватывает без рестарта контейнера. Затрагивает: Atom retrieval quality..', 'Drop stale atoms at retrieval. On/off flag: 0 off, 1 on. Stored in Postgres; after Save the API picks it up without container restart. Affects: Atom retrieval quality..', '1', '0|1', 'Atom retrieval quality.', 'Atom retrieval quality.', false, 1170),
        ('EWA_ATOM_TTL_DEFAULT_SEC', 'int', 'atoms', 'Default atom TTL (sec). Числовой параметр (positive int). Увеличение обычно расширяет лимит/таймаут; уменьшение — ужесточает или ускоряет отказ. Влияет на: Atom expiry..', 'Default atom TTL (sec). Numeric parameter (positive int). Higher values usually widen limits/timeouts; lower values tighten or fail faster. Affects: Atom expiry..', '604800', 'positive int', 'Atom expiry.', 'Atom expiry.', false, 1160),
        ('EWA_COMPANION_ACTION_VALIDATION_ENABLED', 'bool', 'companion', 'Валидация structured actions перед исполнением. Флаг вкл/выкл: 0 — выключено, 1 — включено. Значение хранится в Postgres; после «Сохранить» API подхватывает без рестарта контейнера. Затрагивает: Action pipeline safety..', 'Validate structured actions before execution. On/off flag: 0 off, 1 on. Stored in Postgres; after Save the API picks it up without container restart. Affects: Action pipeline safety..', '0', '0|1', 'Action pipeline safety.', 'Action pipeline safety.', false, 230),
        ('EWA_COMPANION_ADMIN_ENABLED', 'bool', 'companion', 'Показывает раздел «Каталог EWA Companion» в админке продукта (Tools, Action workflows, Настройки). При 0 все GET /api/v1/ewa/admin/companion/* возвращают 503 — UI покажет ошибку загрузки, а не пустой каталог.', 'Shows the EWA Companion catalog section in product admin (Tools, Action workflows, Settings). When 0, GET /api/v1/ewa/admin/companion/* returns 503 — UI shows load error, not an empty catalog.', '0', '0|1', 'EwaCompanionAdminPanel, companion_admin router, operator smoke stack0.', 'EwaCompanionAdminPanel, companion_admin router, operator smoke stack0.', false, 30),
        ('EWA_COMPANION_ADMIN_WRITE', 'bool', 'companion', 'Разрешает мутирующие операции каталога action workflows: Save version, Enable/Disable в Monaco-редакторе. Не блокирует вкладку «Настройки» — bootstrap-флаги (в т.ч. этот) меняются с ролью admin всегда. Для записи нужен также EWA_COMPANION_WF_PG_CATALOG=1.', 'Allows mutating action workflow catalog operations: Save version, Enable/Disable in Monaco editor. Does not block Settings tab — bootstrap flags change with admin role regardless. Also requires EWA_COMPANION_WF_PG_CATALOG=1 for PG writes.', '0', '0|1', 'POST/PUT companion admin workflows, ActionWorkflowsTab write buttons.', 'POST/PUT companion admin workflows, ActionWorkflowsTab write buttons.', false, 40),
        ('EWA_COMPANION_AMBIENT_ACTIONS_ENABLED', 'bool', 'companion', 'Ambient desktop actions без явного запроса. Флаг вкл/выкл: 0 — выключено, 1 — включено. Значение хранится в Postgres; после «Сохранить» API подхватывает без рестарта контейнера. Затрагивает: actions/ambient.py..', 'Ambient desktop actions without explicit ask. On/off flag: 0 off, 1 on. Stored in Postgres; after Save the API picks it up without container restart. Affects: actions/ambient.py..', '0', '0|1', 'actions/ambient.py.', 'actions/ambient.py.', false, 240),
        ('EWA_COMPANION_ANCHOR_SHORT_CIRCUIT_SCORE', 'int', 'companion', 'Score threshold anchor short-circuit. Числовой параметр (0–100). Увеличение обычно расширяет лимит/таймаут; уменьшение — ужесточает или ускоряет отказ. Влияет на: anchor early exit..', 'Anchor short-circuit score threshold. Numeric parameter (0–100). Higher values usually widen limits/timeouts; lower values tighten or fail faster. Affects: anchor early exit..', '85', '0–100', 'anchor early exit.', 'anchor early exit.', false, 890),
        ('EWA_COMPANION_ASYNC_JOBS_ENABLED', 'bool', 'companion', 'Фоновые async jobs спутника: Celery companion_run_task, durable task_runs/steps, SSE progress. Обязателен для action workflows и длительной music/image generation. Без него tools могут выполняться синхронно или пропускаться.', 'Companion background async jobs: Celery companion_run_task, durable runs/steps, SSE progress. Required for action workflows and long music/image generation. Without it, tools may run synchronously or be skipped.', '0', '0|1', 'jobs/executor.py, task_runs tab, «Текущие операции» на столе.', 'jobs/executor.py, task runs tab, desktop operations panel.', false, 100),
        ('EWA_COMPANION_ASYNC_MUSIC_ENABLED', 'bool', 'companion', 'Async music jobs. Флаг вкл/выкл: 0 — выключено, 1 — включено. Значение хранится в Postgres; после «Сохранить» API подхватывает без рестарта контейнера. Затрагивает: Async music workflow steps..', 'Async music jobs. On/off flag: 0 off, 1 on. Stored in Postgres; after Save the API picks it up without container restart. Affects: Async music workflow steps..', '0', '0|1', 'Async music workflow steps.', 'Async music workflow steps.', false, 290),
        ('EWA_COMPANION_AUTO_AMBIENT_FROM_AFFECTIVE', 'bool', 'companion', 'Ambient из affective state. Флаг вкл/выкл: 0 — выключено, 1 — включено. Значение хранится в Postgres; после «Сохранить» API подхватывает без рестарта контейнера. Затрагивает: affective → ambient bridge..', 'Ambient triggers from affective state. On/off flag: 0 off, 1 on. Stored in Postgres; after Save the API picks it up without container restart. Affects: affective → ambient bridge..', '0', '0|1', 'affective → ambient bridge.', 'affective → ambient bridge.', false, 250),
        ('EWA_COMPANION_BACKEND_MUSIC_GENERATION', 'bool', 'companion', 'Atomic tool music_generation в tool_registry (wizard v2 / XL Turbo). Отдельно от action workflow music_full_v1 — это один tool за вызов. Async path: EWA_COMPANION_ASYNC_MUSIC_ENABLED.', 'Atomic music_generation tool in tool_registry (wizard v2 / XL Turbo). Separate from music_full_v1 action workflow — one tool per dispatch. Async path: EWA_COMPANION_ASYNC_MUSIC_ENABLED.', '0', '0|1', 'music_generation handler, Music Studio, user workflows с music step.', 'music_generation handler, Music Studio, user workflows with music step.', false, 280),
        ('EWA_COMPANION_CATALOG_DISCUSS_ENABLED', 'bool', 'companion', 'Discuss mode для catalog find. Флаг вкл/выкл: 0 — выключено, 1 — включено. Значение хранится в Postgres; после «Сохранить» API подхватывает без рестарта контейнера. Затрагивает: catalog_find discuss branch..', 'Discuss mode for catalog find. On/off flag: 0 off, 1 on. Stored in Postgres; after Save the API picks it up without container restart. Affects: catalog_find discuss branch..', '0', '0|1', 'catalog_find discuss branch.', 'catalog_find discuss branch.', false, 330),
        ('EWA_COMPANION_CATALOG_DISCUSS_MAX_CHARS', 'int', 'companion', 'Макс. chars catalog discuss. Числовой параметр (positive int). Увеличение обычно расширяет лимит/таймаут; уменьшение — ужесточает или ускоряет отказ. Влияет на: catalog discuss branch..', 'Max chars catalog discuss. Numeric parameter (positive int). Higher values usually widen limits/timeouts; lower values tighten or fail faster. Affects: catalog discuss branch..', '8000', 'positive int', 'catalog discuss branch.', 'catalog discuss branch.', false, 700),
        ('EWA_COMPANION_CATALOG_FIND', 'bool', 'companion', 'Catalog find tool. Флаг вкл/выкл: 0 — выключено, 1 — включено. Значение хранится в Postgres; после «Сохранить» API подхватывает без рестарта контейнера. Затрагивает: storage/catalog_find.py..', 'Catalog find tool. On/off flag: 0 off, 1 on. Stored in Postgres; after Save the API picks it up without container restart. Affects: storage/catalog_find.py..', '0', '0|1', 'storage/catalog_find.py.', 'storage/catalog_find.py.', false, 340),
        ('EWA_COMPANION_CHAT_CONDENSE_ENABLED', 'bool', 'companion', 'Condense старых сообщений чата. Флаг вкл/выкл: 0 — выключено, 1 — включено. Значение хранится в Postgres; после «Сохранить» API подхватывает без рестарта контейнера. Затрагивает: memory/chat_condense.py..', 'Condense old chat messages. On/off flag: 0 off, 1 on. Stored in Postgres; after Save the API picks it up without container restart. Affects: memory/chat_condense.py..', '0', '0|1', 'memory/chat_condense.py.', 'memory/chat_condense.py.', false, 480),
        ('EWA_COMPANION_CHAT_CONDENSE_MAX_CHARS', 'int', 'companion', 'Макс. chars после condense. Числовой параметр (positive int). Увеличение обычно расширяет лимит/таймаут; уменьшение — ужесточает или ускоряет отказ. Влияет на: chat_condense output..', 'Max chars after condense. Numeric parameter (positive int). Higher values usually widen limits/timeouts; lower values tighten or fail faster. Affects: chat_condense output..', '6000', 'positive int', 'chat_condense output.', 'chat_condense output.', false, 750),
        ('EWA_COMPANION_CHAT_CONDENSE_MIN_MESSAGES', 'int', 'companion', 'Мин. сообщений до condense. Числовой параметр (positive int). Увеличение обычно расширяет лимит/таймаут; уменьшение — ужесточает или ускоряет отказ. Влияет на: chat_condense trigger..', 'Min messages before condense. Numeric parameter (positive int). Higher values usually widen limits/timeouts; lower values tighten or fail faster. Affects: chat_condense trigger..', '8', 'positive int', 'chat_condense trigger.', 'chat_condense trigger.', false, 760),
        ('EWA_COMPANION_CHAT_CONDENSE_TIMEOUT_SEC', 'int', 'companion', 'Таймаут condense LLM. Числовой параметр (positive int). Увеличение обычно расширяет лимит/таймаут; уменьшение — ужесточает или ускоряет отказ. Влияет на: chat_condense sidecar..', 'Condense LLM timeout. Numeric parameter (positive int). Higher values usually widen limits/timeouts; lower values tighten or fail faster. Affects: chat_condense sidecar..', '45', 'positive int', 'chat_condense sidecar.', 'chat_condense sidecar.', false, 770),
        ('EWA_COMPANION_CHAT_LLM_HISTORY_TOKEN_BUDGET', 'int', 'companion', 'Token budget history в chat LLM. Числовой параметр (positive int). Увеличение обычно расширяет лимит/таймаут; уменьшение — ужесточает или ускоряет отказ. Влияет на: chat_turn history trim..', 'History token budget for chat LLM. Numeric parameter (positive int). Higher values usually widen limits/timeouts; lower values tighten or fail faster. Affects: chat_turn history trim..', '6000', 'positive int', 'chat_turn history trim.', 'chat_turn history trim.', false, 780),
        ('EWA_COMPANION_CHAT_MODEL', 'string', 'companion', 'Override chat model (пусто = stack2 default). Строковый параметр (stack2 model id or empty). Пустая строка часто означает «default из stack2/env» — см. доку stack2 LLM contract.', 'Chat model override (empty = stack2 default). String parameter (stack2 model id or empty). Empty often means stack2/env default — see stack2 LLM contract docs.', '', 'stack2 model id or empty', 'Main chat LLM.', 'Main chat LLM.', false, 950),
        ('EWA_COMPANION_CHAT_NUM_CTX', 'int', 'companion', 'num_ctx для основного chat LLM. Числовой параметр (positive int). Увеличение обычно расширяет лимит/таймаут; уменьшение — ужесточает или ускоряет отказ. Влияет на: Размер контекста stack2 chat..', 'num_ctx for main chat LLM. Numeric parameter (positive int). Higher values usually widen limits/timeouts; lower values tighten or fail faster. Affects: stack2 chat context window..', '131072', 'positive int', 'Размер контекста stack2 chat.', 'stack2 chat context window.', false, 500),
        ('EWA_COMPANION_CHAT_NUM_PREDICT', 'int', 'companion', 'num_predict для chat LLM. Числовой параметр (positive int). Увеличение обычно расширяет лимит/таймаут; уменьшение — ужесточает или ускоряет отказ. Влияет на: Макс. токенов ответа..', 'num_predict for chat LLM. Numeric parameter (positive int). Higher values usually widen limits/timeouts; lower values tighten or fail faster. Affects: Max reply tokens..', '1024', 'positive int', 'Макс. токенов ответа.', 'Max reply tokens.', false, 510),
        ('EWA_COMPANION_CHAT_TIMEOUT_SEC', 'int', 'companion', 'Таймаут HTTP chat LLM (сек). Числовой параметр (positive int). Увеличение обычно расширяет лимит/таймаут; уменьшение — ужесточает или ускоряет отказ. Влияет на: chat_turn latency ceiling..', 'HTTP chat LLM timeout (sec). Numeric parameter (positive int). Higher values usually widen limits/timeouts; lower values tighten or fail faster. Affects: chat_turn latency ceiling..', '120', 'positive int', 'chat_turn latency ceiling.', 'chat_turn latency ceiling.', false, 520),
        ('EWA_COMPANION_CHAT_USE_HTTP_LLM', 'bool', 'companion', 'Основной чат спутника через HTTP LLM (stack2 llama-chat), не in-process. При 0 chat_turn может деградировать или отказать — на prod обычно 1. Модель и лимиты: EWA_COMPANION_CHAT_MODEL, CHAT_NUM_CTX, CHAT_TIMEOUT_SEC.', 'Main companion chat via HTTP LLM (stack2 llama-chat), not in-process. When 0, chat_turn may degrade or fail — prod default is 1. Model/limits: EWA_COMPANION_CHAT_MODEL, CHAT_NUM_CTX, CHAT_TIMEOUT_SEC.', '1', '0|1', 'chat_turn.py LLM wire, latency, качество ответов в EwaCompanionChatPanel.', 'chat_turn.py LLM wire, latency, reply quality in companion chat.', false, 180),
        ('EWA_COMPANION_CONTEXT_ANCHOR_ENABLED', 'bool', 'companion', 'Context anchor (сжатый якорь сессии). Флаг вкл/выкл: 0 — выключено, 1 — включено. Значение хранится в Postgres; после «Сохранить» API подхватывает без рестарта контейнера. Затрагивает: context/anchor*.py..', 'Context anchor (compressed session anchor). On/off flag: 0 off, 1 on. Stored in Postgres; after Save the API picks it up without container restart. Affects: context/anchor*.py..', '0', '0|1', 'context/anchor*.py.', 'context/anchor*.py.', false, 200),
        ('EWA_COMPANION_CONTEXT_ANCHOR_LLM', 'bool', 'companion', 'LLM для refresh context anchor. Флаг вкл/выкл: 0 — выключено, 1 — включено. Значение хранится в Postgres; после «Сохранить» API подхватывает без рестарта контейнера. Затрагивает: context/anchor_compose.py..', 'LLM for context anchor refresh. On/off flag: 0 off, 1 on. Stored in Postgres; after Save the API picks it up without container restart. Affects: context/anchor_compose.py..', '0', '0|1', 'context/anchor_compose.py.', 'context/anchor_compose.py.', false, 490),
        ('EWA_COMPANION_CONTEXT_ANCHOR_MAX_CHARS', 'int', 'companion', 'Макс. chars context anchor. Числовой параметр (positive int). Увеличение обычно расширяет лимит/таймаут; уменьшение — ужесточает или ускоряет отказ. Влияет на: anchor storage size..', 'Max context anchor chars. Numeric parameter (positive int). Higher values usually widen limits/timeouts; lower values tighten or fail faster. Affects: anchor storage size..', '4000', 'positive int', 'anchor storage size.', 'anchor storage size.', false, 790),
        ('EWA_COMPANION_CONTEXT_ANCHOR_REFRESH_EVERY_N_TURNS', 'int', 'companion', 'Refresh anchor каждые N turns. Числовой параметр (positive int). Увеличение обычно расширяет лимит/таймаут; уменьшение — ужесточает или ускоряет отказ. Влияет на: anchor refresh cadence..', 'Refresh anchor every N turns. Numeric parameter (positive int). Higher values usually widen limits/timeouts; lower values tighten or fail faster. Affects: anchor refresh cadence..', '6', 'positive int', 'anchor refresh cadence.', 'anchor refresh cadence.', false, 800),
        ('EWA_COMPANION_CONTEXT_ANCHOR_SECTION_ITEM_MAX', 'int', 'companion', 'Макс. items в секции anchor. Числовой параметр (positive int). Увеличение обычно расширяет лимит/таймаут; уменьшение — ужесточает или ускоряет отказ. Влияет на: anchor structure cap..', 'Max items per anchor section. Numeric parameter (positive int). Higher values usually widen limits/timeouts; lower values tighten or fail faster. Affects: anchor structure cap..', '12', 'positive int', 'anchor structure cap.', 'anchor structure cap.', false, 810),
        ('EWA_COMPANION_CONTEXT_ANCHOR_TIMEOUT_SEC', 'int', 'companion', 'Таймаут anchor LLM. Числовой параметр (positive int). Увеличение обычно расширяет лимит/таймаут; уменьшение — ужесточает или ускоряет отказ. Влияет на: anchor_compose..', 'Anchor LLM timeout. Numeric parameter (positive int). Higher values usually widen limits/timeouts; lower values tighten or fail faster. Affects: anchor_compose..', '45', 'positive int', 'anchor_compose.', 'anchor_compose.', false, 820),
        ('EWA_COMPANION_CONTEXT_CONTROLLER_ENABLED', 'bool', 'companion', 'Context controller (prune/budget). Флаг вкл/выкл: 0 — выключено, 1 — включено. Значение хранится в Postgres; после «Сохранить» API подхватывает без рестарта контейнера. Затрагивает: context/controller.py..', 'Context controller (prune/budget). On/off flag: 0 off, 1 on. Stored in Postgres; after Save the API picks it up without container restart. Affects: context/controller.py..', '0', '0|1', 'context/controller.py.', 'context/controller.py.', false, 190),
        ('EWA_COMPANION_CONTEXT_PRUNE_HISTORY_MAX_MESSAGES', 'int', 'companion', 'Макс. сообщений после prune. Числовой параметр (positive int). Увеличение обычно расширяет лимит/таймаут; уменьшение — ужесточает или ускоряет отказ. Влияет на: context controller..', 'Max messages after prune. Numeric parameter (positive int). Higher values usually widen limits/timeouts; lower values tighten or fail faster. Affects: context controller..', '40', 'positive int', 'context controller.', 'context controller.', false, 830),
        ('EWA_COMPANION_CONTEXT_PRUNE_LATENCY_THRESHOLD_MS', 'int', 'companion', 'Latency threshold для prune (мс). Числовой параметр (positive int). Увеличение обычно расширяет лимит/таймаут; уменьшение — ужесточает или ускоряет отказ. Влияет на: context controller..', 'Latency threshold for prune (ms). Numeric parameter (positive int). Higher values usually widen limits/timeouts; lower values tighten or fail faster. Affects: context controller..', '2500', 'positive int', 'context controller.', 'context controller.', false, 840),
        ('EWA_COMPANION_CONTEXT_PRUNE_PROMPT_BUDGET_THRESHOLD', 'int', 'companion', 'Prompt budget threshold для prune. Числовой параметр (positive int). Увеличение обычно расширяет лимит/таймаут; уменьшение — ужесточает или ускоряет отказ. Влияет на: context controller..', 'Prompt budget threshold for prune. Numeric parameter (positive int). Higher values usually widen limits/timeouts; lower values tighten or fail faster. Affects: context controller..', '12000', 'positive int', 'context controller.', 'context controller.', false, 850),
        ('EWA_COMPANION_DOC_BODY_EDIT', 'bool', 'companion', 'Редактирование тела документа через спутника. Флаг вкл/выкл: 0 — выключено, 1 — включено. Значение хранится в Postgres; после «Сохранить» API подхватывает без рестарта контейнера. Затрагивает: doceditor tools..', 'Document body edit via companion. On/off flag: 0 off, 1 on. Stored in Postgres; after Save the API picks it up without container restart. Affects: doceditor tools..', '0', '0|1', 'doceditor tools.', 'doceditor tools.', false, 260),
        ('EWA_COMPANION_DOC_BODY_MAX_ACTION_HTML_CHARS', 'int', 'companion', 'Макс. HTML chars для doc edit action. Числовой параметр (positive int). Увеличение обычно расширяет лимит/таймаут; уменьшение — ужесточает или ускоряет отказ. Влияет на: doceditor safety cap..', 'Max HTML chars for doc edit action. Numeric parameter (positive int). Higher values usually widen limits/timeouts; lower values tighten or fail faster. Affects: doceditor safety cap..', '120000', 'positive int', 'doceditor safety cap.', 'doceditor safety cap.', false, 670),
        ('EWA_COMPANION_DOC_BODY_MAX_DOWNLOAD_BYTES', 'int', 'companion', 'Макс. байт download doc body. Числовой параметр (positive int). Увеличение обычно расширяет лимит/таймаут; уменьшение — ужесточает или ускоряет отказ. Влияет на: doceditor download cap..', 'Max bytes for doc body download. Numeric parameter (positive int). Higher values usually widen limits/timeouts; lower values tighten or fail faster. Affects: doceditor download cap..', '5242880', 'positive int', 'doceditor download cap.', 'doceditor download cap.', false, 680),
        ('EWA_COMPANION_DOC_BODY_TRANSLATE', 'bool', 'companion', 'Перевод тела документа. Флаг вкл/выкл: 0 — выключено, 1 — включено. Значение хранится в Postgres; после «Сохранить» API подхватывает без рестарта контейнера. Затрагивает: doceditor_translate_body..', 'Document body translation. On/off flag: 0 off, 1 on. Stored in Postgres; after Save the API picks it up without container restart. Affects: doceditor_translate_body..', '0', '0|1', 'doceditor_translate_body.', 'doceditor_translate_body.', false, 270),
        ('EWA_COMPANION_DOC_EDIT_PROMPT_BODY_CHARS', 'int', 'companion', 'Chars тела в prompt doc edit. Числовой параметр (positive int). Увеличение обычно расширяет лимит/таймаут; уменьшение — ужесточает или ускоряет отказ. Влияет на: LLM prompt size..', 'Body chars in doc edit prompt. Numeric parameter (positive int). Higher values usually widen limits/timeouts; lower values tighten or fail faster. Affects: LLM prompt size..', '24000', 'positive int', 'LLM prompt size.', 'LLM prompt size.', false, 690),
        ('EWA_COMPANION_DOC_OPEN_VIA_CONTENT_SEARCH', 'bool', 'companion', 'Open doc via content search. Флаг вкл/выкл: 0 — выключено, 1 — включено. Значение хранится в Postgres; после «Сохранить» API подхватывает без рестарта контейнера. Затрагивает: doceditor_content_resolve..', 'Open document via content search. On/off flag: 0 off, 1 on. Stored in Postgres; after Save the API picks it up without container restart. Affects: doceditor_content_resolve..', '0', '0|1', 'doceditor_content_resolve.', 'doceditor_content_resolve.', false, 360),
        ('EWA_COMPANION_DOC_TRANSLATE_DEFAULT_TARGET_LANG', 'string', 'companion', 'Язык перевода документа по умолчанию. Строковый параметр (ISO 639-1 code). Пустая строка часто означает «default из stack2/env» — см. доку stack2 LLM contract.', 'Default document translation target language. String parameter (ISO 639-1 code). Empty often means stack2/env default — see stack2 LLM contract docs.', 'ru', 'ISO 639-1 code', 'doceditor translate.', 'doceditor translate.', false, 1020),
        ('EWA_COMPANION_EPISODES_REEMBED_BATCH', 'int', 'companion', 'Batch size episodic reembed. Числовой параметр (positive int). Увеличение обычно расширяет лимит/таймаут; уменьшение — ужесточает или ускоряет отказ. Влияет на: episodic_reembed_task..', 'Episodic reembed batch size. Numeric parameter (positive int). Higher values usually widen limits/timeouts; lower values tighten or fail faster. Affects: episodic_reembed_task..', '32', 'positive int', 'episodic_reembed_task.', 'episodic_reembed_task.', false, 710),
        ('EWA_COMPANION_EPISODES_REEMBED_ROW_DELAY_MS', 'int', 'companion', 'Delay между строками reembed (мс). Числовой параметр (positive int). Увеличение обычно расширяет лимит/таймаут; уменьшение — ужесточает или ускоряет отказ. Влияет на: episodic_reembed_task throttle..', 'Delay between reembed rows (ms). Numeric parameter (positive int). Higher values usually widen limits/timeouts; lower values tighten or fail faster. Affects: episodic_reembed_task throttle..', '50', 'positive int', 'episodic_reembed_task throttle.', 'episodic_reembed_task throttle.', false, 720),
        ('EWA_COMPANION_EPISODIC_INTENT_PRIORITIZE', 'bool', 'companion', 'Приоритет episodic intent в retrieval. Флаг вкл/выкл: 0 — выключено, 1 — включено. Значение хранится в Postgres; после «Сохранить» API подхватывает без рестарта контейнера. Затрагивает: memory/retrieval.py..', 'Prioritize episodic intent in retrieval. On/off flag: 0 off, 1 on. Stored in Postgres; after Save the API picks it up without container restart. Affects: memory/retrieval.py..', '0', '0|1', 'memory/retrieval.py.', 'memory/retrieval.py.', false, 370),
        ('EWA_COMPANION_EPISODIC_RERANK_ENABLED', 'bool', 'companion', 'Rerank episodic hits при retrieval. Флаг вкл/выкл: 0 — выключено, 1 — включено. Значение хранится в Postgres; после «Сохранить» API подхватывает без рестарта контейнера. Затрагивает: memory/retrieval episodic branch..', 'Rerank episodic hits during retrieval. On/off flag: 0 off, 1 on. Stored in Postgres; after Save the API picks it up without container restart. Affects: memory/retrieval episodic branch..', '0', '0|1', 'memory/retrieval episodic branch.', 'memory/retrieval episodic branch.', false, 70),
        ('EWA_COMPANION_EPISODIC_SESSION_TOPIC_PRIORITIZE', 'bool', 'companion', 'Приоритет session topic episodic. Флаг вкл/выкл: 0 — выключено, 1 — включено. Значение хранится в Postgres; после «Сохранить» API подхватывает без рестарта контейнера. Затрагивает: memory/retrieval.py..', 'Prioritize session topic episodic. On/off flag: 0 off, 1 on. Stored in Postgres; after Save the API picks it up without container restart. Affects: memory/retrieval.py..', '0', '0|1', 'memory/retrieval.py.', 'memory/retrieval.py.', false, 380),
        ('EWA_COMPANION_EVOLUTION_AUTO_COOLDOWN_SEC', 'int', 'companion', 'Cooldown auto evolution (сек). Числовой параметр (positive int). Увеличение обычно расширяет лимит/таймаут; уменьшение — ужесточает или ускоряет отказ. Влияет на: evolution_chat_trigger..', 'Auto evolution cooldown (sec). Numeric parameter (positive int). Higher values usually widen limits/timeouts; lower values tighten or fail faster. Affects: evolution_chat_trigger..', '3600', 'positive int', 'evolution_chat_trigger.', 'evolution_chat_trigger.', false, 610),
        ('EWA_COMPANION_EVOLUTION_AUTO_EVERY_N_USER_TURNS', 'int', 'companion', 'Auto evolution каждые N user turns. Числовой параметр (positive int). Увеличение обычно расширяет лимит/таймаут; уменьшение — ужесточает или ускоряет отказ. Влияет на: evolution_chat_trigger..', 'Auto evolution every N user turns. Numeric parameter (positive int). Higher values usually widen limits/timeouts; lower values tighten or fail faster. Affects: evolution_chat_trigger..', '12', 'positive int', 'evolution_chat_trigger.', 'evolution_chat_trigger.', false, 620),
        ('EWA_COMPANION_EVOLUTION_AUTO_FROM_CHAT', 'bool', 'companion', 'Auto evolution из чата. Флаг вкл/выкл: 0 — выключено, 1 — включено. Значение хранится в Postgres; после «Сохранить» API подхватывает без рестарта контейнера. Затрагивает: evolution_chat_trigger..', 'Auto evolution from chat turns. On/off flag: 0 off, 1 on. Stored in Postgres; after Save the API picks it up without container restart. Affects: evolution_chat_trigger..', '0', '0|1', 'evolution_chat_trigger.', 'evolution_chat_trigger.', false, 390),
        ('EWA_COMPANION_EVOLUTION_AUTO_MIN_USER_TURNS', 'int', 'companion', 'Мин. user turns до auto evolution. Числовой параметр (positive int). Увеличение обычно расширяет лимит/таймаут; уменьшение — ужесточает или ускоряет отказ. Влияет на: evolution_chat_trigger..', 'Min user turns before auto evolution. Numeric parameter (positive int). Higher values usually widen limits/timeouts; lower values tighten or fail faster. Affects: evolution_chat_trigger..', '4', 'positive int', 'evolution_chat_trigger.', 'evolution_chat_trigger.', false, 630),
        ('EWA_COMPANION_EVOLUTION_IDEMPOTENCY_TTL_SEC', 'int', 'companion', 'TTL idempotency evolution (сек). Числовой параметр (positive int). Увеличение обычно расширяет лимит/таймаут; уменьшение — ужесточает или ускоряет отказ. Влияет на: Duplicate evolution guard..', 'Evolution idempotency TTL (sec). Numeric parameter (positive int). Higher values usually widen limits/timeouts; lower values tighten or fail faster. Affects: Duplicate evolution guard..', '86400', 'positive int', 'Duplicate evolution guard.', 'Duplicate evolution guard.', false, 640),
        ('EWA_COMPANION_EVOLUTION_MODEL', 'string', 'companion', 'Override evolution LLM model. Строковый параметр (stack2 model id or empty). Пустая строка часто означает «default из stack2/env» — см. доку stack2 LLM contract.', 'Evolution LLM model override. String parameter (stack2 model id or empty). Empty often means stack2/env default — see stack2 LLM contract docs.', '', 'stack2 model id or empty', 'Evolution workers.', 'Evolution workers.', false, 1010),
        ('EWA_COMPANION_EVOLUTION_NUM_PREDICT', 'int', 'companion', 'num_predict evolution LLM. Числовой параметр (positive int). Увеличение обычно расширяет лимит/таймаут; уменьшение — ужесточает или ускоряет отказ. Влияет на: Evolution summary length..', 'Evolution LLM num_predict. Numeric parameter (positive int). Higher values usually widen limits/timeouts; lower values tighten or fail faster. Affects: Evolution summary length..', '512', 'positive int', 'Evolution summary length.', 'Evolution summary length.', false, 600),
        ('EWA_COMPANION_EVOLUTION_TIMEOUT_SEC', 'int', 'companion', 'Таймаут evolution LLM. Числовой параметр (positive int). Увеличение обычно расширяет лимит/таймаут; уменьшение — ужесточает или ускоряет отказ. Влияет на: evolution workers..', 'Evolution LLM timeout. Numeric parameter (positive int). Higher values usually widen limits/timeouts; lower values tighten or fail faster. Affects: evolution workers..', '90', 'positive int', 'evolution workers.', 'evolution workers.', false, 590),
        ('EWA_COMPANION_EVOLUTION_USE_LLM', 'bool', 'companion', 'LLM для persona evolution summaries. Флаг вкл/выкл: 0 — выключено, 1 — включено. Значение хранится в Postgres; после «Сохранить» API подхватывает без рестарта контейнера. Затрагивает: Evolution tick worker..', 'LLM for persona evolution summaries. On/off flag: 0 off, 1 on. Stored in Postgres; after Save the API picks it up without container restart. Affects: Evolution tick worker..', '0', '0|1', 'Evolution tick worker.', 'Evolution tick worker.', false, 160),
        ('EWA_COMPANION_HCM_EPISODIC_ENABLED', 'bool', 'companion', 'Episodic memory слой HCM. Флаг вкл/выкл: 0 — выключено, 1 — включено. Значение хранится в Postgres; после «Сохранить» API подхватывает без рестарта контейнера. Затрагивает: Episodic ingest и reembed tasks..', 'HCM episodic memory layer. On/off flag: 0 off, 1 on. Stored in Postgres; after Save the API picks it up without container restart. Affects: Episodic ingest and reembed tasks..', '0', '0|1', 'Episodic ingest и reembed tasks.', 'Episodic ingest and reembed tasks.', false, 130),
        ('EWA_COMPANION_HCM_RETRIEVAL_ENABLED', 'bool', 'companion', 'HCM retrieval в контекст чата: episodic + semantic память из Postgres/Qdrant. Бюджет времени — EWA_COMPANION_RETRIEVAL_BUDGET_MS. Episodic ingest — HCM_EPISODIC_ENABLED.', 'HCM retrieval in chat context: episodic + semantic memory from Postgres/Qdrant. Time budget: EWA_COMPANION_RETRIEVAL_BUDGET_MS. Episodic ingest: HCM_EPISODIC_ENABLED.', '0', '0|1', 'memory/hcm_store.py, memory block в system prompt.', 'memory/hcm_store.py, memory block in system prompt.', false, 120),
        ('EWA_COMPANION_IMAGE_GENERATION_ENABLED', 'bool', 'companion', 'Генерация фоновых картинок спутником через UGS (tool image_generation). Требует рабочий UGS/stack2 и type_key/slug из соседних параметров. Не включает маркетинговую AMKA — только desktop companion contour.', 'Companion background image generation via UGS (image_generation tool). Requires working UGS/stack2 and neighboring type_key/slug settings. Marketing AMKA is out of scope — desktop companion only.', '0', '0|1', 'companion_image_generation.py, UGS generate_and_wait, operations panel.', 'companion_image_generation.py, UGS generate_and_wait, operations panel.', false, 300),
        ('EWA_COMPANION_IMAGE_GENERATION_TYPE_KEY', 'string', 'companion', 'UGS type_key для генерации картинки из чата спутника. Строковый параметр (UGS type_key). Пустая строка часто означает «default из stack2/env» — см. доку stack2 LLM contract.', 'UGS type_key for companion chat image generation. String parameter (UGS type_key). Empty often means stack2/env default — see stack2 LLM contract docs.', 'desktop_ai_chat_image_01_top', 'UGS type_key', 'UnifiedGenerationService.generate_and_wait type_key.', 'UnifiedGenerationService.generate_and_wait type_key.', false, 960),
        ('EWA_COMPANION_IMAGE_GENERATION_WORKFLOW_SLUG', 'string', 'companion', 'ComfyUI workflow template slug для companion image UGS. Строковый параметр (workflow slug). Пустая строка часто означает «default из stack2/env» — см. доку stack2 LLM contract.', 'ComfyUI workflow template slug for companion image UGS. String parameter (workflow slug). Empty often means stack2/env default — see stack2 LLM contract docs.', '01_top', 'workflow slug', 'input_data workflow_template в companion_image_generation.', 'input_data workflow_template in companion_image_generation.', false, 970),
        ('EWA_COMPANION_INFER_DESKTOP_THEME_PATCH', 'bool', 'companion', 'Inference patch desktop theme. Флаг вкл/выкл: 0 — выключено, 1 — включено. Значение хранится в Postgres; после «Сохранить» API подхватывает без рестарта контейнера. Затрагивает: ux/desktop_theme_inference.py..', 'Infer desktop theme patch. On/off flag: 0 off, 1 on. Stored in Postgres; after Save the API picks it up without container restart. Affects: ux/desktop_theme_inference.py..', '0', '0|1', 'ux/desktop_theme_inference.py.', 'ux/desktop_theme_inference.py.', false, 320),
        ('EWA_COMPANION_INFER_OPEN_FROM_USER', 'bool', 'companion', 'Inference open_app из текста пользователя. Флаг вкл/выкл: 0 — выключено, 1 — включено. Значение хранится в Postgres; после «Сохранить» API подхватывает без рестарта контейнера. Затрагивает: ux/action_inference.py..', 'Infer open_app from user text. On/off flag: 0 off, 1 on. Stored in Postgres; after Save the API picks it up without container restart. Affects: ux/action_inference.py..', '0', '0|1', 'ux/action_inference.py.', 'ux/action_inference.py.', false, 310),
        ('EWA_COMPANION_INTENT_MODEL', 'string', 'companion', 'Override intent model. Строковый параметр (stack2 model id or empty). Пустая строка часто означает «default из stack2/env» — см. доку stack2 LLM contract.', 'Intent model override. String parameter (stack2 model id or empty). Empty often means stack2/env default — see stack2 LLM contract docs.', '', 'stack2 model id or empty', 'Intent sidecar.', 'Intent sidecar.', false, 980),
        ('EWA_COMPANION_INTENT_NUM_PREDICT', 'int', 'companion', 'num_predict intent planner. Числовой параметр (positive int). Увеличение обычно расширяет лимит/таймаут; уменьшение — ужесточает или ускоряет отказ. Влияет на: Intent JSON size..', 'Intent planner num_predict. Numeric parameter (positive int). Higher values usually widen limits/timeouts; lower values tighten or fail faster. Affects: Intent JSON size..', '256', 'positive int', 'Intent JSON size.', 'Intent JSON size.', false, 560),
        ('EWA_COMPANION_INTENT_PLANNER', 'bool', 'companion', 'LLM intent planner sidecar. Флаг вкл/выкл: 0 — выключено, 1 — включено. Значение хранится в Postgres; после «Сохранить» API подхватывает без рестарта контейнера. Затрагивает: Structured intents до tool router..', 'LLM intent planner sidecar. On/off flag: 0 off, 1 on. Stored in Postgres; after Save the API picks it up without container restart. Affects: Structured intents before tool router..', '0', '0|1', 'Structured intents до tool router.', 'Structured intents before tool router.', false, 140),
        ('EWA_COMPANION_INTENT_PLANNER_FORCE', 'bool', 'companion', 'Force intent planner каждый turn. Флаг вкл/выкл: 0 — выключено, 1 — включено. Значение хранится в Postgres; после «Сохранить» API подхватывает без рестарта контейнера. Затрагивает: intent_planner sidecar..', 'Force intent planner every turn. On/off flag: 0 off, 1 on. Stored in Postgres; after Save the API picks it up without container restart. Affects: intent_planner sidecar..', '0', '0|1', 'intent_planner sidecar.', 'intent_planner sidecar.', false, 400),
        ('EWA_COMPANION_INTENT_PLANNER_MIN_CONFIDENCE', 'float', 'companion', 'Мин. confidence intent planner. Дробный порог (0–1). Используется как gate confidence/score: ниже порога — fallback на другую ветку orchestrator.', 'Min intent planner confidence. Float threshold (0–1). Used as confidence/score gate: below threshold — orchestrator fallback branch.', '0.5', '0–1', 'Intent acceptance gate.', 'Intent acceptance gate.', false, 910),
        ('EWA_COMPANION_INTENT_TIMEOUT_SEC', 'int', 'companion', 'Таймаут intent sidecar. Числовой параметр (positive int). Увеличение обычно расширяет лимит/таймаут; уменьшение — ужесточает или ускоряет отказ. Влияет на: intent_planner..', 'Intent sidecar timeout. Numeric parameter (positive int). Higher values usually widen limits/timeouts; lower values tighten or fail faster. Affects: intent_planner..', '30', 'positive int', 'intent_planner.', 'intent_planner.', false, 550),
        ('EWA_COMPANION_LISTING_ORDINALS', 'bool', 'companion', 'Ordinal listing в shell context. Флаг вкл/выкл: 0 — выключено, 1 — включено. Значение хранится в Postgres; после «Сохранить» API подхватывает без рестарта контейнера. Затрагивает: shell_listing_ordinals sidecar..', 'Ordinal listing in shell context. On/off flag: 0 off, 1 on. Stored in Postgres; after Save the API picks it up without container restart. Affects: shell_listing_ordinals sidecar..', '0', '0|1', 'shell_listing_ordinals sidecar.', 'shell_listing_ordinals sidecar.', false, 350),
        ('EWA_COMPANION_LLM_WIRE_ACTION_LOG_MAX', 'int', 'companion', 'Макс. action log entries в wire. Числовой параметр (positive int). Увеличение обычно расширяет лимит/таймаут; уменьшение — ужесточает или ускоряет отказ. Влияет на: llm_bandwidth logging..', 'Max action log entries in wire. Numeric parameter (positive int). Higher values usually widen limits/timeouts; lower values tighten or fail faster. Affects: llm_bandwidth logging..', '24', 'positive int', 'llm_bandwidth logging.', 'llm_bandwidth logging.', false, 870),
        ('EWA_COMPANION_LLM_WIRE_ROLLUP_SNIPPET_MAX', 'int', 'companion', 'Макс. chars rollup snippet. Числовой параметр (positive int). Увеличение обычно расширяет лимит/таймаут; уменьшение — ужесточает или ускоряет отказ. Влияет на: llm_bandwidth rollup..', 'Max rollup snippet chars. Numeric parameter (positive int). Higher values usually widen limits/timeouts; lower values tighten or fail faster. Affects: llm_bandwidth rollup..', '280', 'positive int', 'llm_bandwidth rollup.', 'llm_bandwidth rollup.', false, 880),
        ('EWA_COMPANION_META_EVOLUTION_BEAT_ENABLED', 'bool', 'companion', 'Periodic meta-evolution beat. Флаг вкл/выкл: 0 — выключено, 1 — включено. Значение хранится в Postgres; после «Сохранить» API подхватывает без рестарта контейнера. Затрагивает: meta_schedule beat..', 'Periodic meta-evolution beat. On/off flag: 0 off, 1 on. Stored in Postgres; after Save the API picks it up without container restart. Affects: meta_schedule beat..', '0', '0|1', 'meta_schedule beat.', 'meta_schedule beat.', false, 470),
        ('EWA_COMPANION_META_EVOLUTION_BEAT_INTERVAL_MIN', 'int', 'companion', 'Интервал meta-evolution beat (мин). Числовой параметр (positive int). Увеличение обычно расширяет лимит/таймаут; уменьшение — ужесточает или ускоряет отказ. Влияет на: meta_schedule..', 'Meta-evolution beat interval (min). Numeric parameter (positive int). Higher values usually widen limits/timeouts; lower values tighten or fail faster. Affects: meta_schedule..', '60', 'positive int', 'meta_schedule.', 'meta_schedule.', false, 650),
        ('EWA_COMPANION_META_EVOLUTION_ENABLED', 'bool', 'companion', 'Meta-evolution sweep по профилям. Флаг вкл/выкл: 0 — выключено, 1 — включено. Значение хранится в Postgres; после «Сохранить» API подхватывает без рестарта контейнера. Затрагивает: meta_evolution_sweep_task..', 'Meta-evolution sweep across profiles. On/off flag: 0 off, 1 on. Stored in Postgres; after Save the API picks it up without container restart. Affects: meta_evolution_sweep_task..', '0', '0|1', 'meta_evolution_sweep_task.', 'meta_evolution_sweep_task.', false, 170),
        ('EWA_COMPANION_META_EVOLUTION_SWEEP_LIMIT', 'int', 'companion', 'Лимит профилей за sweep. Числовой параметр (positive int). Увеличение обычно расширяет лимит/таймаут; уменьшение — ужесточает или ускоряет отказ. Влияет на: meta_evolution_sweep_task..', 'Profile limit per meta sweep. Numeric parameter (positive int). Higher values usually widen limits/timeouts; lower values tighten or fail faster. Affects: meta_evolution_sweep_task..', '50', 'positive int', 'meta_evolution_sweep_task.', 'meta_evolution_sweep_task.', false, 660),
        ('EWA_COMPANION_OBSERVATION_RATE_LIMIT_PER_MIN', 'int', 'companion', 'Rate limit shell observations/мин. Числовой параметр (positive int). Увеличение обычно расширяет лимит/таймаут; уменьшение — ужесточает или ускоряет отказ. Влияет на: Observation ingest..', 'Shell observation rate limit per minute. Numeric parameter (positive int). Higher values usually widen limits/timeouts; lower values tighten or fail faster. Affects: Observation ingest..', '30', 'positive int', 'Observation ingest.', 'Observation ingest.', false, 580),
        ('EWA_COMPANION_PLAN_ENABLED', 'bool', 'companion', 'Server-first планы (цели и задачи): plan_v1 tool, plans API, roadmap output_surface. Клиент не строит roadmap — только отображает server plan (ADR EWA-COMPANION-SERVER-PLANS). LLM-структурирование шагов — EWA_COMPANION_PLAN_LLM_ENABLED.', 'Server-first plans (goals/tasks): plan_v1 tool, plans API, roadmap output_surface. Client does not build roadmaps — only displays server plan (EWA-COMPANION-SERVER-PLANS ADR). LLM structuring: EWA_COMPANION_PLAN_LLM_ENABLED.', '0', '0|1', 'plans/service.py, CompanionOutputRoadmapMode, plan_task_complete_v1.', 'plans/service.py, CompanionOutputRoadmapMode, plan_task_complete_v1.', false, 110),
        ('EWA_COMPANION_PLAN_LLM_ENABLED', 'bool', 'companion', 'LLM для plan steps. Флаг вкл/выкл: 0 — выключено, 1 — включено. Значение хранится в Postgres; после «Сохранить» API подхватывает без рестарта контейнера. Затрагивает: plans/service.py..', 'LLM for plan steps. On/off flag: 0 off, 1 on. Stored in Postgres; after Save the API picks it up without container restart. Affects: plans/service.py..', '0', '0|1', 'plans/service.py.', 'plans/service.py.', false, 410),
        ('EWA_COMPANION_PLAN_MODEL', 'string', 'companion', 'Override plan LLM model. Строковый параметр (stack2 model id or empty). Пустая строка часто означает «default из stack2/env» — см. доку stack2 LLM contract.', 'Plan LLM model override. String parameter (stack2 model id or empty). Empty often means stack2/env default — see stack2 LLM contract docs.', '', 'stack2 model id or empty', 'Plans service LLM.', 'Plans service LLM.', false, 1000),
        ('EWA_COMPANION_RETRIEVAL_BUDGET_MS', 'int', 'companion', 'Бюджет времени retrieval (мс). Числовой параметр (positive int). Увеличение обычно расширяет лимит/таймаут; уменьшение — ужесточает или ускоряет отказ. Влияет на: memory/retrieval.py..', 'Retrieval time budget (ms). Numeric parameter (positive int). Higher values usually widen limits/timeouts; lower values tighten or fail faster. Affects: memory/retrieval.py..', '800', 'positive int', 'memory/retrieval.py.', 'memory/retrieval.py.', false, 570),
        ('EWA_COMPANION_RETRIEVAL_ROUTER_ENABLED', 'bool', 'companion', 'Retrieval router для каталога/HCM. Флаг вкл/выкл: 0 — выключено, 1 — включено. Значение хранится в Postgres; после «Сохранить» API подхватывает без рестарта контейнера. Затрагивает: memory/retrieval.py..', 'Retrieval router for catalog/HCM. On/off flag: 0 off, 1 on. Stored in Postgres; after Save the API picks it up without container restart. Affects: memory/retrieval.py..', '0', '0|1', 'memory/retrieval.py.', 'memory/retrieval.py.', false, 210),
        ('EWA_COMPANION_SELF_CORRECTION_ENABLED', 'bool', 'companion', 'Self-correction pass после ответа. Флаг вкл/выкл: 0 — выключено, 1 — включено. Значение хранится в Postgres; после «Сохранить» API подхватывает без рестарта контейнера. Затрагивает: affective/self_correction.py..', 'Self-correction pass after reply. On/off flag: 0 off, 1 on. Stored in Postgres; after Save the API picks it up without container restart. Affects: affective/self_correction.py..', '0', '0|1', 'affective/self_correction.py.', 'affective/self_correction.py.', false, 150),
        ('EWA_COMPANION_SELF_CORRECTION_EPISODES_ENABLED', 'bool', 'companion', 'Self-correction с episodic context. Флаг вкл/выкл: 0 — выключено, 1 — включено. Значение хранится в Postgres; после «Сохранить» API подхватывает без рестарта контейнера. Затрагивает: self_correction episodes branch..', 'Self-correction with episodic context. On/off flag: 0 off, 1 on. Stored in Postgres; after Save the API picks it up without container restart. Affects: self_correction episodes branch..', '0', '0|1', 'self_correction episodes branch.', 'self_correction episodes branch.', false, 420),
        ('EWA_COMPANION_SEMANTIC_CATALOG_ENABLED', 'bool', 'companion', 'Semantic catalog augment. Флаг вкл/выкл: 0 — выключено, 1 — включено. Значение хранится в Postgres; после «Сохранить» API подхватывает без рестарта контейнера. Затрагивает: storage/semantic_catalog_augment.py..', 'Semantic catalog augment. On/off flag: 0 off, 1 on. Stored in Postgres; after Save the API picks it up without container restart. Affects: storage/semantic_catalog_augment.py..', '0', '0|1', 'storage/semantic_catalog_augment.py.', 'storage/semantic_catalog_augment.py.', false, 220),
        ('EWA_COMPANION_SERVER_FIRST_V2', 'bool', 'companion', 'Server-first v2 chat path. Флаг вкл/выкл: 0 — выключено, 1 — включено. Значение хранится в Postgres; после «Сохранить» API подхватывает без рестарта контейнера. Затрагивает: server_first/v2.py..', 'Server-first v2 chat path. On/off flag: 0 off, 1 on. Stored in Postgres; after Save the API picks it up without container restart. Affects: server_first/v2.py..', '0', '0|1', 'server_first/v2.py.', 'server_first/v2.py.', false, 430),
        ('EWA_COMPANION_SESSION_COMPRESS_TOKEN_BUDGET', 'int', 'companion', 'Token budget session compress. Числовой параметр (positive int). Увеличение обычно расширяет лимит/таймаут; уменьшение — ужесточает или ускоряет отказ. Влияет на: system_budget.py..', 'Session compress token budget. Numeric parameter (positive int). Higher values usually widen limits/timeouts; lower values tighten or fail faster. Affects: system_budget.py..', '8000', 'positive int', 'system_budget.py.', 'system_budget.py.', false, 860),
        ('EWA_COMPANION_TOOL_ROUTER_ENABLED', 'bool', 'companion', 'Sidecar Qwen tool router: structured {tool, confidence, slots} до исполнения atomic tools. Режим rollout задаётся EWA_COMPANION_TOOL_ROUTER_MODE (shadow → partial → full). При 0 orchestrator использует regex/intent branches без FC-router.', 'Sidecar Qwen tool router: structured {tool, confidence, slots} before atomic tool execution. Rollout mode: EWA_COMPANION_TOOL_ROUTER_MODE (shadow → partial → full). When 0, orchestrator uses regex/intent branches without FC router.', '1', '0|1', 'tool_router sidecar, CompanionRouterTool allowlists, chat structured actions.', 'tool_router sidecar, CompanionRouterTool allowlists, chat structured actions.', false, 80),
        ('EWA_COMPANION_TOOL_ROUTER_MAX_TOKENS', 'int', 'companion', 'max_tokens tool router. Числовой параметр (positive int). Увеличение обычно расширяет лимит/таймаут; уменьшение — ужесточает или ускоряет отказ. Влияет на: Router JSON output size..', 'Tool router max_tokens. Numeric parameter (positive int). Higher values usually widen limits/timeouts; lower values tighten or fail faster. Affects: Router JSON output size..', '384', 'positive int', 'Router JSON output size.', 'Router JSON output size.', false, 540),
        ('EWA_COMPANION_TOOL_ROUTER_MIN_CONFIDENCE', 'float', 'companion', 'Мин. confidence tool router. Дробный порог (0–1). Используется как gate confidence/score: ниже порога — fallback на другую ветку orchestrator.', 'Min tool router confidence. Float threshold (0–1). Used as confidence/score gate: below threshold — orchestrator fallback branch.', '0.62', '0–1', 'Fallback если ниже порога.', 'Fallback when below threshold.', false, 900),
        ('EWA_COMPANION_TOOL_ROUTER_MODE', 'string', 'companion', 'Режим tool router: shadow — только лог без исполнения; partial — узкий allowlist tools; full — полный ROUTER_FULL_TOOLS. Меняйте постепенно после smoke в shadow. Связан с EWA_COMPANION_TOOL_ROUTER_MIN_CONFIDENCE.', 'Tool router mode: shadow — log only; partial — narrow tool allowlist; full — ROUTER_FULL_TOOLS. Roll out gradually after shadow smoke. Tied to EWA_COMPANION_TOOL_ROUTER_MIN_CONFIDENCE.', 'partial', 'shadow|partial|full', 'tool_router_dispatch.py, routing_policy PRE_TOOL branches.', 'tool_router_dispatch.py, routing_policy PRE_TOOL branches.', false, 920),
        ('EWA_COMPANION_TOOL_ROUTER_MODEL', 'string', 'companion', 'Имя модели tool router. Строковый параметр (stack2 model id). Пустая строка часто означает «default из stack2/env» — см. доку stack2 LLM contract.', 'Tool router model name. String parameter (stack2 model id). Empty often means stack2/env default — see stack2 LLM contract docs.', 'Qwen3-4B-Instruct-2507-Q4_K_M.gguf', 'stack2 model id', 'Sidecar model selection.', 'Sidecar model selection.', false, 930),
        ('EWA_COMPANION_TOOL_ROUTER_TIMEOUT_SEC', 'int', 'companion', 'Таймаут tool router sidecar. Числовой параметр (positive int). Увеличение обычно расширяет лимит/таймаут; уменьшение — ужесточает или ускоряет отказ. Влияет на: tool_router sidecar..', 'Tool router sidecar timeout. Numeric parameter (positive int). Higher values usually widen limits/timeouts; lower values tighten or fail faster. Affects: tool_router sidecar..', '12', 'positive int', 'tool_router sidecar.', 'tool_router sidecar.', false, 530),
        ('EWA_COMPANION_TOOL_ROUTER_URL', 'string', 'companion', 'Override URL tool router (пусто = stack2 default). Строковый параметр (http(s) URL or empty). Пустая строка часто означает «default из stack2/env» — см. доку stack2 LLM contract.', 'Tool router URL override (empty = stack2 default). String parameter (http(s) URL or empty). Empty often means stack2/env default — see stack2 LLM contract docs.', 'http://stack2-llama-tool-router:8080', 'http(s) URL or empty', 'Sidecar HTTP endpoint.', 'Sidecar HTTP endpoint.', false, 940),
        ('EWA_COMPANION_TRUST_CLASSIFY_TIMEOUT_SEC', 'int', 'companion', 'Таймаут trust classify sidecar. Числовой параметр (positive int). Увеличение обычно расширяет лимит/таймаут; уменьшение — ужесточает или ускоряет отказ. Влияет на: trust_classify.py..', 'Trust classify sidecar timeout. Numeric parameter (positive int). Higher values usually widen limits/timeouts; lower values tighten or fail faster. Affects: trust_classify.py..', '20', 'positive int', 'trust_classify.py.', 'trust_classify.py.', false, 730),
        ('EWA_COMPANION_USER_WORKFLOWS_ENABLED', 'bool', 'companion', 'Личные цепочки пользователя: phrase-триггеры, CRUD /api/v1/ewa/companion-user-workflows, builder в чате (output_surface). Требует EWA_COMPANION_WF_ENGINE_ENABLED=1. При 0 сохранённые цепочки остаются в PG, но auto-trigger и builder intent отключены.', 'End-user personal workflows: phrase triggers, CRUD API, chat builder (output_surface). Requires EWA_COMPANION_WF_ENGINE_ENABLED=1. When 0, saved rows remain in PG but auto-triggers and builder intent are off.', '1', '0|1', 'user_workflow_triggers.py, companion-user-workflows router, CompanionOutputSurface на фронте.', 'user_workflow_triggers.py, companion-user-workflows router, CompanionOutputSurface UI.', false, 60),
        ('EWA_COMPANION_VOICE_ENABLED', 'bool', 'companion', 'Голосовой контур спутника: STT/TTS через voice-gateway, voice mode в composer. Не включает фоновое прослушивание без действия пользователя (on-demand).', 'Companion voice pipeline: STT/TTS via voice-gateway, composer voice mode. Does not enable always-on listening — on-demand only.', '0', '0|1', 'voice-gateway API, EwaCompanionChatPanel voice button.', 'voice-gateway API, EwaCompanionChatPanel voice button.', false, 90),
        ('EWA_COMPANION_WF_DOC_PACKAGE_V1', 'bool', 'companion', 'Pilot action workflow «пакет документов»: создание/сбор нескольких файлов в каталоге по declarative definition. Используется операторским каталогом; для end-user — личные цепочки с file_create/doc_insert.', 'Pilot document package workflow: create/assemble multiple catalog files from a declarative definition. Operator catalog; end-users use personal chains with file_create/doc_insert.', '0', '0|1', 'doc_package_v1 definition, file_* tools в executor.', 'doc_package_v1 definition, file_* tools in executor.', false, 20),
        ('EWA_COMPANION_WF_ENGINE_ENABLED', 'bool', 'companion', 'Мастер-переключатель declarative action workflows — цепочек server-side tools с durable steps в Postgres и Celery. При 0 pilot workflows (music_full_v1, doc_package_v1) и личные цепочки пользователя не стартуют, даже если отдельные EWA_COMPANION_WF_* = 1. На prod обычно включают вместе с EWA_COMPANION_ASYNC_JOBS_ENABLED=1; для каталога из админки нужен EWA_COMPANION_WF_PG_CATALOG=1.', 'Master switch for declarative action workflows — server-side tool chains with durable Postgres steps and Celery. When 0, pilot workflows and user personal chains do not start even if individual EWA_COMPANION_WF_* flags are 1. On prod enable together with EWA_COMPANION_ASYNC_JOBS_ENABLED=1; PG catalog requires EWA_COMPANION_WF_PG_CATALOG=1.', '0', '0|1', 'Все action workflows, generic starter, task runs в «Текущие операции», admin Action workflows tab.', 'All action workflows, generic starter, task runs panel, admin Action workflows tab.', false, 0),
        ('EWA_COMPANION_WF_MUSIC_FULL_V1', 'bool', 'companion', 'Pilot action workflow «полный цикл музыки»: lyrics → params → style → generate через music_generation tool. Стартует по operator catalog trigger или user workflow с тем же tool. Не путать с EWA_COMPANION_BACKEND_MUSIC_GENERATION (atomic tool).', 'Pilot action workflow for the full music cycle via music_generation tool. Starts from operator catalog trigger or a user workflow step. Not the same as EWA_COMPANION_BACKEND_MUSIC_GENERATION (atomic tool flag).', '0', '0|1', 'music_full_cycle_v1 definition, Celery executor, панель «Текущие операции».', 'music_full_cycle_v1 definition, Celery executor, operations panel.', false, 10),
        ('EWA_COMPANION_WF_PG_CATALOG', 'bool', 'companion', 'Загружать определения action workflows из Postgres (ewa_companion_workflow_catalog), а не только code builtins. Без этого флага admin видит workflows read-only из кода; Enable/Save в PG не применяются. Включайте после миграций WF и перед operator smoke §12.', 'Load action workflow definitions from Postgres (ewa_companion_workflow_catalog), not code builtins only. Without it, admin sees code workflows read-only; PG Enable/Save have no effect. Enable after WF migrations and before operator smoke §12.', '0', '0|1', 'workflow_catalog PG, Action workflows tab, match_action_workflow_async.', 'workflow_catalog PG, Action workflows tab, match_action_workflow_async.', false, 50),
        ('EWA_COMPANION_WORKFLOW_FILE_FOCUS_ENABLED', 'bool', 'companion', 'Chat workflow file_focus. Флаг вкл/выкл: 0 — выключено, 1 — включено. Значение хранится в Postgres; после «Сохранить» API подхватывает без рестарта контейнера. Затрагивает: Reserved chat workflow..', 'Chat workflow file_focus. On/off flag: 0 off, 1 on. Stored in Postgres; after Save the API picks it up without container restart. Affects: Reserved chat workflow..', '0', '0|1', 'Reserved chat workflow.', 'Reserved chat workflow.', false, 440),
        ('EWA_COMPANION_WORKFLOW_MODEL', 'string', 'companion', 'Override workflow LLM model. Строковый параметр (stack2 model id or empty). Пустая строка часто означает «default из stack2/env» — см. доку stack2 LLM contract.', 'Workflow LLM model override. String parameter (stack2 model id or empty). Empty often means stack2/env default — see stack2 LLM contract docs.', '', 'stack2 model id or empty', 'Action workflow LLM steps.', 'Action workflow LLM steps.', false, 990),
        ('EWA_COMPANION_WORKFLOW_PLAN_MONTH_ENABLED', 'bool', 'companion', 'Chat workflow plan_month. Флаг вкл/выкл: 0 — выключено, 1 — включено. Значение хранится в Postgres; после «Сохранить» API подхватывает без рестарта контейнера. Затрагивает: Reserved chat workflow..', 'Chat workflow plan_month. On/off flag: 0 off, 1 on. Stored in Postgres; after Save the API picks it up without container restart. Affects: Reserved chat workflow..', '0', '0|1', 'Reserved chat workflow.', 'Reserved chat workflow.', false, 450),
        ('EWA_COMPANION_WORKFLOW_REFLECT_WEEK_ENABLED', 'bool', 'companion', 'Chat workflow reflect_week. Флаг вкл/выкл: 0 — выключено, 1 — включено. Значение хранится в Postgres; после «Сохранить» API подхватывает без рестарта контейнера. Затрагивает: reflect_week runner..', 'Chat workflow reflect_week. On/off flag: 0 off, 1 on. Stored in Postgres; after Save the API picks it up without container restart. Affects: reflect_week runner..', '0', '0|1', 'reflect_week runner.', 'reflect_week runner.', false, 460),
        ('EWA_COMPANION_WRATH_CLASSIFY_TIMEOUT_SEC', 'int', 'companion', 'Таймаут Arlika wrath classify. Числовой параметр (positive int). Увеличение обычно расширяет лимит/таймаут; уменьшение — ужесточает или ускоряет отказ. Влияет на: arlika_wrath_classify.py..', 'Arlika wrath classify timeout. Numeric parameter (positive int). Higher values usually widen limits/timeouts; lower values tighten or fail faster. Affects: arlika_wrath_classify.py..', '20', 'positive int', 'arlika_wrath_classify.py.', 'arlika_wrath_classify.py.', false, 740),
        ('EWA_DESKTOP_ORCH_APP_ALLOWLIST', 'csv', 'orchestration', 'CSV allowlist desktop app ids for orch. Строковый параметр (comma-separated app ids). Пустая строка часто означает «default из stack2/env» — см. доку stack2 LLM contract.', 'CSV allowlist of desktop app ids for orch. String parameter (comma-separated app ids). Empty often means stack2/env default — see stack2 LLM contract docs.', '', 'comma-separated app ids', 'Desktop orch app open guard.', 'Desktop orch app open guard.', false, 1130),
        ('EWA_HEALTH_PG_PROBE', 'bool', 'infrastructure', 'Include EWA Postgres in /api/health. Флаг вкл/выкл: 0 — выключено, 1 — включено. Значение хранится в Postgres; после «Сохранить» API подхватывает без рестарта контейнера. Затрагивает: ewa_health_snapshot..', 'Include EWA Postgres in /api/health. On/off flag: 0 off, 1 on. Stored in Postgres; after Save the API picks it up without container restart. Affects: ewa_health_snapshot..', '1', '0|1', 'ewa_health_snapshot.', 'ewa_health_snapshot.', false, 1180),
        ('EWA_ORCH_ATTACH_CONTENT_SHELL_HINT', 'bool', 'orchestration', 'Attach content shell hints. Флаг вкл/выкл: 0 — выключено, 1 — включено. Значение хранится в Postgres; после «Сохранить» API подхватывает без рестарта контейнера. Затрагивает: Shell hint expansion..', 'Attach content shell hints. On/off flag: 0 off, 1 on. Stored in Postgres; after Save the API picks it up without container restart. Affects: Shell hint expansion..', '0', '0|1', 'Shell hint expansion.', 'Shell hint expansion.', false, 1060),
        ('EWA_ORCH_ATTACH_DOCUMENTS_SHELL_HINT', 'bool', 'orchestration', 'Attach documents shell hints. Флаг вкл/выкл: 0 — выключено, 1 — включено. Значение хранится в Postgres; после «Сохранить» API подхватывает без рестарта контейнера. Затрагивает: Shell hint expansion..', 'Attach documents shell hints. On/off flag: 0 off, 1 on. Stored in Postgres; after Save the API picks it up without container restart. Affects: Shell hint expansion..', '0', '0|1', 'Shell hint expansion.', 'Shell hint expansion.', false, 1070),
        ('EWA_ORCH_ATTACH_UGS_HTTP', 'bool', 'orchestration', 'Attach UGS profile via HTTP. Флаг вкл/выкл: 0 — выключено, 1 — включено. Значение хранится в Postgres; после «Сохранить» API подхватывает без рестарта контейнера. Затрагивает: Orch context enrichment..', 'Attach UGS profile via HTTP. On/off flag: 0 off, 1 on. Stored in Postgres; after Save the API picks it up without container restart. Affects: Orch context enrichment..', '0', '0|1', 'Orch context enrichment.', 'Orch context enrichment.', false, 1050),
        ('EWA_ORCH_LLM_CONTEXT_LOG', 'bool', 'orchestration', 'Log LLM context for orch (verbose). Флаг вкл/выкл: 0 — выключено, 1 — включено. Значение хранится в Postgres; после «Сохранить» API подхватывает без рестарта контейнера. Затрагивает: Operator debugging..', 'Log LLM context for orch (verbose). On/off flag: 0 off, 1 on. Stored in Postgres; after Save the API picks it up without container restart. Affects: Operator debugging..', '0', '0|1', 'Operator debugging.', 'Operator debugging.', false, 1080),
        ('EWA_ORCH_LLM_SLIM_DOMAIN_HINTS_UTF8', 'bool', 'orchestration', 'Slim domain hints UTF-8 for orch LLM. Флаг вкл/выкл: 0 — выключено, 1 — включено. Значение хранится в Postgres; после «Сохранить» API подхватывает без рестарта контейнера. Затрагивает: Prompt size for orch..', 'Slim domain hints UTF-8 for orch LLM. On/off flag: 0 off, 1 on. Stored in Postgres; after Save the API picks it up without container restart. Affects: Prompt size for orch..', '0', '0|1', 'Prompt size for orch.', 'Prompt size for orch.', false, 1090),
        ('EWA_ORCH_LLM_SLIM_OBSERVATION_WINDOWS', 'bool', 'orchestration', 'Slim observation windows for orch LLM. Флаг вкл/выкл: 0 — выключено, 1 — включено. Значение хранится в Postgres; после «Сохранить» API подхватывает без рестарта контейнера. Затрагивает: Prompt size for orch..', 'Slim observation windows for orch LLM. On/off flag: 0 off, 1 on. Stored in Postgres; after Save the API picks it up without container restart. Affects: Prompt size for orch..', '0', '0|1', 'Prompt size for orch.', 'Prompt size for orch.', false, 1100),
        ('EWA_ORCH_SSE_KEEPALIVE_SEC', 'int', 'orchestration', 'SSE keep-alive interval (sec). Числовой параметр (positive int). Увеличение обычно расширяет лимит/таймаут; уменьшение — ужесточает или ускоряет отказ. Влияет на: Long orch streams..', 'SSE keep-alive interval (sec). Numeric parameter (positive int). Higher values usually widen limits/timeouts; lower values tighten or fail faster. Affects: Long orch streams..', '2', 'positive int', 'Long orch streams.', 'Long orch streams.', false, 1110),
        ('EWA_ORCH_UGS_PROFILE', 'string', 'orchestration', 'UGS profile id for orch attach. Строковый параметр (profile name or empty). Пустая строка часто означает «default из stack2/env» — см. доку stack2 LLM contract.', 'UGS profile id for orch attach. String parameter (profile name or empty). Empty often means stack2/env default — see stack2 LLM contract docs.', '', 'profile name or empty', 'UGS HTTP attach.', 'UGS HTTP attach.', false, 1120),
        ('EWA_ORCH_USE_ELITEEW_HTTP', 'bool', 'orchestration', 'EliteEW HTTP self-call для orch. Флаг вкл/выкл: 0 — выключено, 1 — включено. Значение хранится в Postgres; после «Сохранить» API подхватывает без рестарта контейнера. Затрагивает: desktop/runtime orch drivers..', 'EliteEW HTTP self-call for orch. On/off flag: 0 off, 1 on. Stored in Postgres; after Save the API picks it up without container restart. Affects: desktop/runtime orch drivers..', '1', '0|1', 'desktop/runtime orch drivers.', 'desktop/runtime orch drivers.', false, 1040),
        ('EWA_ORCH_USE_HTTP_LLM', 'bool', 'orchestration', 'Desktop orchestration (/api/v1/ewa/desktop/*) использует HTTP LLM (stack2) для LLM-шагов оркестратора стола. Отдельно от companion chat LLM — тот же stack2, другой prompt/wire.', 'Desktop orchestration uses HTTP LLM (stack2) for orchestrator LLM steps. Separate from companion chat LLM — same stack2, different prompt/wire.', '1', '0|1', 'http_orch_llm.py, ewaDesktopOrchApi, desktop shell drivers.', 'http_orch_llm.py, ewaDesktopOrchApi, desktop shell drivers.', false, 1030),
